'use client'

import { useState, useEffect, useCallback, useRef } from 'react'
import { motion, Reorder, AnimatePresence } from 'framer-motion'
import {
    Eye, EyeOff, GripVertical, Smartphone, Monitor, Tablet,
    Clock, Save, Sparkles, Palette, ChevronLeft,
    Layout, Type, Image, MessageSquare, Star,
    Phone, FileText, ShoppingCart, Loader2, Check,
} from 'lucide-react'
import { useEsnaf } from '@/context/EsnafContext'
import VersiyonGecmisi from '@/components/Dashboard/VersiyonGecmisi'

// ── Blok tipleri ───────────────────────────────────────────────────────────

interface SiteBlok {
    id: string
    baslik: string
    ikon: string
    gorunur: boolean
    tip: string
}

// ── Tema Paletleri ─────────────────────────────────────────────────────────

interface TemaPaleti {
    id: string
    ad: string
    emoji: string
    renkler: { bg: string; kart: string; vurgu: string; metin: string }
}

const TEMA_PALETLERI: TemaPaleti[] = [
    { id: 'toprak', ad: 'Toprak Tonları', emoji: '🏔️', renkler: { bg: '#1a1510', kart: '#231e16', vurgu: '#c08552', metin: '#f5e6d3' } },
    { id: 'neon', ad: 'Neon Teknoloji', emoji: '⚡', renkler: { bg: '#050510', kart: '#0a0a1a', vurgu: '#00f5ff', metin: '#e0e0ff' } },
    { id: 'kurumsal', ad: 'Kurumsal Güven', emoji: '🏢', renkler: { bg: '#0f1419', kart: '#1a2332', vurgu: '#3b82f6', metin: '#e8edf3' } },
    { id: 'okyanus', ad: 'Okyanus', emoji: '🌊', renkler: { bg: '#0a1628', kart: '#0f2035', vurgu: '#06b6d4', metin: '#d5eef7' } },
    { id: 'gece', ad: 'Gece Modası', emoji: '🌙', renkler: { bg: '#0a0a0a', kart: '#141414', vurgu: '#a855f7', metin: '#f0e8ff' } },
    { id: 'pastel', ad: 'Pastel Rüya', emoji: '🌸', renkler: { bg: '#fdf6f0', kart: '#fff8f2', vurgu: '#f472b6', metin: '#3d2c2e' } },
]

// ── Varsayılan bloklar ─────────────────────────────────────────────────────

const VARSAYILAN_BLOKLAR: SiteBlok[] = [
    { id: 'hero', baslik: 'Hero / Karşılama', ikon: '🎯', gorunur: true, tip: 'hero' },
    { id: 'hizmetler', baslik: 'Hizmetlerimiz', ikon: '🔧', gorunur: true, tip: 'hizmetler' },
    { id: 'hakkimizda', baslik: 'Hakkımızda', ikon: '📖', gorunur: true, tip: 'hakkimizda' },
    { id: 'galeri', baslik: 'Galeri', ikon: '🖼️', gorunur: true, tip: 'galeri' },
    { id: 'yorumlar', baslik: 'Müşteri Yorumları', ikon: '⭐', gorunur: true, tip: 'yorumlar' },
    { id: 'fiyatlar', baslik: 'Fiyat Listesi', ikon: '💰', gorunur: false, tip: 'fiyatlar' },
    { id: 'ekip', baslik: 'Ekibimiz', ikon: '👥', gorunur: false, tip: 'ekip' },
    { id: 'iletisim', baslik: 'İletişim', ikon: '📞', gorunur: true, tip: 'iletisim' },
    { id: 'whatsapp', baslik: 'WhatsApp Butonu', ikon: '💬', gorunur: true, tip: 'ozel' },
    { id: 'sss', baslik: 'Sık Sorulan Sorular', ikon: '❓', gorunur: false, tip: 'ozel' },
]

// ── AI Stil Seçenekleri ────────────────────────────────────────────────────

const AI_STILLER = [
    { id: 'ikna_edici', ad: 'Daha İkna Edici', emoji: '🔥' },
    { id: 'kurumsal', ad: 'Daha Kurumsal', emoji: '🏢' },
    { id: 'kisa', ad: 'Daha Kısa', emoji: '✂️' },
    { id: 'samimi', ad: 'Daha Samimi', emoji: '🤝' },
    { id: 'esprili', ad: 'Esprili', emoji: '😄' },
]

// ── Blok İkonu ─────────────────────────────────────────────────────────────

function BlokIkonu({ tip }: { tip: string }) {
    const cls = 'w-4 h-4'
    switch (tip) {
        case 'hero': return <Layout className={cls} />
        case 'hizmetler': return <FileText className={cls} />
        case 'hakkimizda': return <Type className={cls} />
        case 'galeri': return <Image className={cls} />
        case 'iletisim': return <Phone className={cls} />
        case 'yorumlar': return <Star className={cls} />
        case 'fiyatlar': return <ShoppingCart className={cls} />
        case 'ekip': return <MessageSquare className={cls} />
        default: return <Layout className={cls} />
    }
}

// ═══════════════════════════════════════════════════════════════════════════
// EDITOR PAGE
// ═══════════════════════════════════════════════════════════════════════════

export default function SiteEditorPage() {
    const { esnafId } = useEsnaf()
    const [bloklar, setBloklar] = useState<SiteBlok[]>(VARSAYILAN_BLOKLAR)
    const [siteUrl, setSiteUrl] = useState<string | null>(null)
    const [onizlemeMod, setOnizlemeMod] = useState<'masaustu' | 'tablet' | 'mobil'>('masaustu')
    const [aktifTema, setAktifTema] = useState('toprak')
    const [gecmisAcik, setGecmisAcik] = useState(false)
    const [kaydetYukleniyor, setKaydetYukleniyor] = useState(false)
    const [kaydetBasarili, setKaydetBasarili] = useState(false)

    // AI Sihirli Değnek
    const [aiSeciliMetin, setAiSeciliMetin] = useState('')
    const [aiYukleniyor, setAiYukleniyor] = useState(false)
    const [aiSonuc, setAiSonuc] = useState<string | null>(null)

    const iframeRef = useRef<HTMLIFrameElement>(null)

    // ── Esnaf verisini çek ─────────────────────────────────────────────────

    useEffect(() => {
        if (!esnafId) return
        fetch(`/api/esnaf/${esnafId}`, { credentials: 'include' })
            .then(r => r.json())
            .then(d => { if (d.subdomainUrl) setSiteUrl(d.subdomainUrl) })
            .catch(() => { })
    }, [esnafId])

    // ── Blok görünürlüğü toggle ────────────────────────────────────────────

    const blokToggle = useCallback((id: string) => {
        setBloklar(prev => prev.map(b =>
            b.id === id ? { ...b, gorunur: !b.gorunur } : b
        ))
    }, [])

    // ── Tema değiştir ──────────────────────────────────────────────────────

    const temaUygula = useCallback((temaId: string) => {
        setAktifTema(temaId)
        const tema = TEMA_PALETLERI.find(t => t.id === temaId)
        if (tema && iframeRef.current?.contentDocument) {
            try {
                const root = iframeRef.current.contentDocument.documentElement
                root.style.setProperty('--renk-arkaplan', tema.renkler.bg)
                root.style.setProperty('--renk-kart', tema.renkler.kart)
                root.style.setProperty('--renk-vurgu', tema.renkler.vurgu)
                root.style.setProperty('--renk-metin', tema.renkler.metin)
            } catch { /* cross-origin */ }
        }
    }, [])

    // ── AI metin yeniden yaz ───────────────────────────────────────────────

    const aiYenidenYaz = useCallback(async (stil: string) => {
        if (!aiSeciliMetin) return
        setAiYukleniyor(true)
        try {
            const res = await fetch('/api/site/ai-rewrite', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ metin: aiSeciliMetin, stil }),
            })
            const data = await res.json()
            if (data.ok) setAiSonuc(data.yeniMetin)
        } catch { /* sessiz */ }
        finally { setAiYukleniyor(false) }
    }, [aiSeciliMetin])

    // ── Kaydet / Yayınla ───────────────────────────────────────────────────

    const kaydetVeYayinla = useCallback(async () => {
        if (!esnafId) return
        setKaydetYukleniyor(true)
        try {
            await fetch('/api/site/guncelle', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    esnafId,
                    bloklar: bloklar.map(b => ({ id: b.id, gorunur: b.gorunur })),
                    temaId: aktifTema,
                }),
            })
            setKaydetBasarili(true)
            setTimeout(() => setKaydetBasarili(false), 3000)
        } catch { /* sessiz */ }
        finally { setKaydetYukleniyor(false) }
    }, [esnafId, bloklar, aktifTema])

    // ── Önizleme genişliği ─────────────────────────────────────────────────

    const onizlemeGenislik = onizlemeMod === 'masaustu' ? '100%' : onizlemeMod === 'tablet' ? '768px' : '375px'

    // ═════════════════════════════════════════════════════════════════════════
    // RENDER
    // ═════════════════════════════════════════════════════════════════════════

    return (
        <div className="fixed inset-0 bg-background flex flex-col z-40">

            {/* ── Üst Bar ─────────────────────────────────────────────────── */}
            <div className="h-14 bg-background border-b border-white/10 flex items-center justify-between px-4 shrink-0">
                {/* Sol */}
                <div className="flex items-center gap-3">
                    <a href="/dashboard/sitem" className="flex items-center gap-2 text-muted-foreground-400 hover:text-white transition text-sm font-bold">
                        <ChevronLeft className="w-4 h-4" /> Geri
                    </a>
                    <div className="w-px h-6 bg-white/10" />
                    <h1 className="text-white font-syne font-bold text-sm">
                        Site <span className="text-rust">Editörü</span>
                    </h1>
                </div>

                {/* Orta — Cihaz toggle */}
                <div className="flex items-center gap-1 bg-white/5 rounded-xl p-1">
                    {([
                        { id: 'masaustu' as const, icon: Monitor, label: 'Masaüstü' },
                        { id: 'tablet' as const, icon: Tablet, label: 'Tablet' },
                        { id: 'mobil' as const, icon: Smartphone, label: 'Mobil' },
                    ]).map(d => (
                        <button
                            key={d.id}
                            onClick={() => setOnizlemeMod(d.id)}
                            className={`p-2 rounded-lg transition ${onizlemeMod === d.id
                                ? 'bg-rust text-white'
                                : 'text-muted-foreground-400 hover:text-white'
                                }`}
                            title={d.label}
                        >
                            <d.icon className="w-4 h-4" />
                        </button>
                    ))}
                </div>

                {/* Sağ */}
                <div className="flex items-center gap-2">
                    <button
                        onClick={() => setGecmisAcik(true)}
                        className="flex items-center gap-2 px-3 py-2 rounded-xl bg-white/5 hover:bg-white/10 text-muted-foreground-300 hover:text-white transition text-xs font-bold"
                    >
                        <Clock className="w-3.5 h-3.5" /> Geçmiş
                    </button>
                    <button
                        onClick={kaydetVeYayinla}
                        disabled={kaydetYukleniyor}
                        className={`flex items-center gap-2 px-4 py-2 rounded-xl font-bold text-xs transition ${kaydetBasarili
                            ? 'bg-green-500 text-white'
                            : 'bg-rust hover:bg-rust/90 text-white'
                            } disabled:opacity-50`}
                    >
                        {kaydetYukleniyor ? (
                            <Loader2 className="w-3.5 h-3.5 animate-spin" />
                        ) : kaydetBasarili ? (
                            <Check className="w-3.5 h-3.5" />
                        ) : (
                            <Save className="w-3.5 h-3.5" />
                        )}
                        {kaydetBasarili ? 'Kaydedildi!' : 'Yayınla'}
                    </button>
                </div>
            </div>

            {/* ── İçerik ────────────────────────────────────────────────────── */}
            <div className="flex-1 flex overflow-hidden">

                {/* ── SOL PANEL (320px) ──────────────────────────────────────── */}
                <div className="w-80 bg-background border-r border-white/10 flex flex-col shrink-0 overflow-hidden">

                    {/* Bölümler */}
                    <div className="flex-1 overflow-y-auto p-4 space-y-1">
                        <div className="flex items-center gap-2 mb-3">
                            <Layout className="w-4 h-4 text-rust" />
                            <h2 className="text-white text-xs font-bold uppercase tracking-wider">Bölümler</h2>
                            <span className="text-muted-foreground-500 text-[10px] ml-auto">{bloklar.filter(b => b.gorunur).length}/{bloklar.length}</span>
                        </div>

                        <Reorder.Group
                            axis="y"
                            values={bloklar}
                            onReorder={setBloklar}
                            className="space-y-1"
                        >
                            {bloklar.map(blok => (
                                <Reorder.Item
                                    key={blok.id}
                                    value={blok}
                                    className={`flex items-center gap-3 px-3 py-2.5 rounded-xl cursor-grab active:cursor-grabbing transition-all group ${blok.gorunur
                                        ? 'bg-white/5 hover:bg-white/10'
                                        : 'bg-transparent opacity-40 hover:opacity-60'
                                        }`}
                                >
                                    <GripVertical className="w-3.5 h-3.5 text-muted-foreground-600 group-hover:text-muted-foreground-400 shrink-0" />
                                    <span className="text-base shrink-0">{blok.ikon}</span>
                                    <span className={`text-sm font-semibold flex-1 truncate ${blok.gorunur ? 'text-white' : 'text-muted-foreground-500'}`}>
                                        {blok.baslik}
                                    </span>
                                    <button
                                        onClick={(e) => { e.stopPropagation(); blokToggle(blok.id) }}
                                        className="p-1 rounded-lg hover:bg-white/10 transition shrink-0"
                                    >
                                        {blok.gorunur ? (
                                            <Eye className="w-3.5 h-3.5 text-green-400" />
                                        ) : (
                                            <EyeOff className="w-3.5 h-3.5 text-muted-foreground-500" />
                                        )}
                                    </button>
                                </Reorder.Item>
                            ))}
                        </Reorder.Group>
                    </div>

                    {/* Tema Paletleri */}
                    <div className="border-t border-white/10 p-4">
                        <div className="flex items-center gap-2 mb-3">
                            <Palette className="w-4 h-4 text-rust" />
                            <h3 className="text-white text-xs font-bold uppercase tracking-wider">Tema</h3>
                        </div>
                        <div className="grid grid-cols-3 gap-2">
                            {TEMA_PALETLERI.map(tema => (
                                <button
                                    key={tema.id}
                                    onClick={() => temaUygula(tema.id)}
                                    className={`flex flex-col items-center gap-1.5 p-2.5 rounded-xl transition-all ${aktifTema === tema.id
                                        ? 'bg-rust/20 ring-2 ring-rust'
                                        : 'bg-white/5 hover:bg-white/10'
                                        }`}
                                >
                                    <div className="flex gap-0.5">
                                        {Object.values(tema.renkler).slice(0, 3).map((r, i) => (
                                            <div key={i} className="w-3 h-3 rounded-full" style={{ backgroundColor: r }} />
                                        ))}
                                    </div>
                                    <span className="text-[10px] text-muted-foreground-300 font-bold truncate w-full text-center">{tema.ad}</span>
                                </button>
                            ))}
                        </div>
                    </div>

                    {/* ✨ AI Sihirli Değnek */}
                    <div className="border-t border-white/10 p-4">
                        <div className="flex items-center gap-2 mb-3">
                            <Sparkles className="w-4 h-4 text-amber-400" />
                            <h3 className="text-white text-xs font-bold uppercase tracking-wider">AI Sihiri</h3>
                        </div>
                        <div className="bg-white/5 rounded-xl p-3">
                            <textarea
                                value={aiSeciliMetin}
                                onChange={e => setAiSeciliMetin(e.target.value)}
                                placeholder="Değiştirmek istediğiniz metni buraya yapıştırın..."
                                className="w-full bg-transparent text-white text-xs resize-none outline-none placeholder:text-muted-foreground-500 mb-2"
                                rows={2}
                            />
                            <div className="flex flex-wrap gap-1">
                                {AI_STILLER.map(stil => (
                                    <button
                                        key={stil.id}
                                        onClick={() => aiYenidenYaz(stil.id)}
                                        disabled={!aiSeciliMetin || aiYukleniyor}
                                        className="px-2 py-1 rounded-lg bg-white/5 hover:bg-amber-500/20 text-muted-foreground-300 hover:text-amber-300 text-[10px] font-bold transition disabled:opacity-30"
                                    >
                                        {stil.emoji} {stil.ad}
                                    </button>
                                ))}
                            </div>
                            {aiYukleniyor && (
                                <div className="flex items-center gap-2 mt-2 text-amber-400 text-xs">
                                    <Loader2 className="w-3 h-3 animate-spin" /> Yazılıyor...
                                </div>
                            )}
                            <AnimatePresence>
                                {aiSonuc && (
                                    <motion.div
                                        initial={{ opacity: 0, y: 5 }}
                                        animate={{ opacity: 1, y: 0 }}
                                        exit={{ opacity: 0 }}
                                        className="mt-2 p-2 bg-amber-500/10 border border-amber-500/20 rounded-lg"
                                    >
                                        <p className="text-amber-200 text-xs leading-relaxed">{aiSonuc}</p>
                                        <button
                                            onClick={() => {
                                                navigator.clipboard.writeText(aiSonuc)
                                                setAiSonuc(null)
                                                setAiSeciliMetin('')
                                            }}
                                            className="mt-1.5 text-[10px] text-amber-400 font-bold hover:text-amber-300"
                                        >
                                            📋 Kopyala ve Kapat
                                        </button>
                                    </motion.div>
                                )}
                            </AnimatePresence>
                        </div>
                    </div>

                </div>

                {/* ── SAĞ PANEL — Canlı Önizleme ────────────────────────────── */}
                <div className="flex-1 flex items-center justify-center bg-[#0a0a0f] p-4 overflow-hidden">
                    <motion.div
                        layout
                        className="bg-white rounded-2xl overflow-hidden shadow-2xl flex flex-col"
                        style={{
                            width: onizlemeGenislik,
                            maxWidth: '100%',
                            height: '100%',
                        }}
                        transition={{ type: 'spring', damping: 20, stiffness: 200 }}
                    >
                        {/* Browser chrome */}
                        <div className="flex items-center gap-2 px-4 py-2.5 bg-stone-100 border-b border-border-200 shrink-0">
                            <div className="flex gap-1.5">
                                <div className="w-2.5 h-2.5 rounded-full bg-red-400" />
                                <div className="w-2.5 h-2.5 rounded-full bg-amber-400" />
                                <div className="w-2.5 h-2.5 rounded-full bg-green-400" />
                            </div>
                            <div className="flex-1 bg-white text-center text-muted-foreground-400 font-mono text-[10px] py-1 rounded-md border border-border-200 truncate px-3">
                                {siteUrl || 'site-adresi.kepenk.site'}
                            </div>
                        </div>

                        {/* iframe */}
                        <div className="flex-1 relative">
                            {siteUrl ? (
                                <iframe
                                    ref={iframeRef}
                                    src={siteUrl}
                                    className="w-full h-full border-0 absolute inset-0"
                                    title="Canlı Önizleme"
                                />
                            ) : (
                                <div className="w-full h-full flex items-center justify-center bg-background">
                                    <div className="text-center">
                                        <div className="text-4xl mb-3">🏗️</div>
                                        <p className="text-white font-syne font-bold">Site Yükleniyor...</p>
                                        <p className="text-muted-foreground-400 text-xs mt-1">Siteniz henüz oluşturulmamış olabilir</p>
                                    </div>
                                </div>
                            )}
                        </div>
                    </motion.div>
                </div>

            </div>

            {/* ── Zaman Makinesi Drawer ──────────────────────────────────────── */}
            {esnafId && (
                <VersiyonGecmisi
                    esnafId={esnafId}
                    acik={gecmisAcik}
                    onKapat={() => setGecmisAcik(false)}
                    onRollback={() => {
                        if (iframeRef.current) {
                            iframeRef.current.src = iframeRef.current.src
                        }
                    }}
                />
            )}
        </div>
    )
}
